        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a < 2**128);
        vm.assume(address(this).balance >= a);
        try c.addToBalance{value: a}() {} catch { return; }
        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
        uint256 bal;
        try c.getBalance(address(this)) returns (uint256 __r) { bal = __r; } catch { return; }
        assertTrue(!reverted && bal == 0);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
